import gurobipy as gp
from gurobipy import GRB
records = LEGACY_RECORDS
school_capacity = {}
for rec in records:
    if rec['source'].endswith('school_capacity.csv'):
        school = rec['values']['School']
        capacity = int(rec['values']['Capacity'])
        school_capacity[school] = capacity
schools = list(school_capacity.keys())
neighborhood_population = {}
for rec in records:
    if rec['source'].endswith('neighborhoods_population.csv'):
        n = rec['values']['Neighborhood']
        w = int(rec['values']['Population_White'])
        nw = int(rec['values']['Population_NonWhite'])
        neighborhood_population[n] = {'White': w, 'NonWhite': nw}
neighborhoods = list(neighborhood_population.keys())
distance = {}
for rec in records:
    if rec['source'].endswith('distance.csv'):
        s = rec['values']['School']
        distance[s] = {}
        for n in neighborhoods:
            distance[s][n] = float(rec['values'][n])
P_W = sum((neighborhood_population[n]['White'] for n in neighborhoods))
P_NW = sum((neighborhood_population[n]['NonWhite'] for n in neighborhoods))
district_white_ratio = P_W / (P_W + P_NW)
white_ratio_lb = 0.5
white_ratio_ub = 0.7
m = gp.Model('school_assignment')
x_white_vars = m.addVars(schools, neighborhoods, lb=0, vtype=GRB.INTEGER, name='')
x_nonwhite_vars = m.addVars(schools, neighborhoods, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((distance[s][n] * (x_white_vars[s, n] + x_nonwhite_vars[s, n]) for s in schools for n in neighborhoods)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_white_vars[s, n] for s in schools)) == neighborhood_population[n]['White'] for n in neighborhoods), name='')
m.addConstrs((gp.quicksum((x_nonwhite_vars[s, n] for s in schools)) == neighborhood_population[n]['NonWhite'] for n in neighborhoods), name='')
m.addConstrs((gp.quicksum((x_white_vars[s, n] + x_nonwhite_vars[s, n] for n in neighborhoods)) <= school_capacity[s] for s in schools), name='')
for s in schools:
    total_white = gp.quicksum((x_white_vars[s, n] for n in neighborhoods))
    total_students = gp.quicksum((x_white_vars[s, n] + x_nonwhite_vars[s, n] for n in neighborhoods))
    m.addConstr(total_white >= white_ratio_lb * total_students, name=f'white_lb_{s}')
    m.addConstr(total_white <= white_ratio_ub * total_students, name=f'white_ub_{s}')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')